-- Run after the legacy shooting release suite and the cap migration.
reset role;
update public.team_memberships set status='active';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000001')->'challenge'->>'daily_cap')::int=250,'Existing challenges default to 250');
select public.create_capped_shooting_challenge('30000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','Capped competition',current_date,current_date+3,'America/Vancouver',250);
select public.create_capped_shooting_challenge('30000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','Capped competition',current_date,current_date+3,'America/Vancouver',250);
select public.test_denied($q$select public.create_capped_shooting_challenge('30000000-0000-0000-0000-000000000003','10000000-0000-0000-0000-000000000001','Capped competition',current_date,current_date+3,'America/Vancouver',300)$q$,'22023','Changed publication retry rejected');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'total')::int=0,'Unlogged players start at zero under cap');
select public.test_assert(public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->'rank'='null'::jsonb,'Unlogged players remain unranked');
reset role;
-- Fixture clock: backfill eligible dates without exposing a production clock override.
update public.shooting_challenges set start_date=current_date-2 where id='30000000-0000-0000-0000-000000000003';
update public.shooting_challenge_players set enrolled_at=now()-interval '5 days' where challenge_id='30000000-0000-0000-0000-000000000003';
set role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',false);
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',current_date-1,3000,0,'90000000-0000-0000-0000-000000000001');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'total')::int=250,'3000 shots count as 250 leaderboard shots');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'bonus_total')::int=2750,'2750 extra shots retained as bonus');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'raw_total')::int=3000,'Raw effort preserved');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'bonus_boss')::boolean,'Saved bonus earns Bonus Boss');
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000002',current_date-1,250,0,gen_random_uuid());
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->1->>'rank')::int=1,'250 and 3000 tie at the daily cap');
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',current_date-2,200,0,gen_random_uuid());
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'total')::int=450,'Cap applied per calendar day, not challenge total');
select public.test_assert((public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',current_date-1,3000,0,'90000000-0000-0000-0000-000000000001')->>'replayed')::boolean,'Retry preserves one raw entry');
select public.test_assert((public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',current_date-1,500,0,gen_random_uuid())->>'conflict')::boolean,'Stale save cannot overwrite raw total');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',10000,250)$q$,'42501','Parent cannot change cap');
select public.test_denied($q$select public.create_capped_shooting_challenge(gen_random_uuid(),'10000000-0000-0000-0000-000000000001','Forged',current_date,current_date,'UTC',10000)$q$,'42501','Parent cannot create custom cap');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000003',false);
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',500,250)$q$,'42501','Unrelated account cannot change cap');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',false);
select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',100,250);
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'total')::int=200,'Coach cap reduction recalculates every day');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'raw_total')::int=3200,'Cap edit never changes raw shots');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',400,250)$q$,'40001','Stale coach cap edit rejected');
select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',400,100);
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'total')::int=600,'Coach cap increase restores credited portion');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',0,400)$q$,'22023','Zero cap rejected');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',10001,400)$q$,'22023','Invalid large cap rejected');
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',null,400)$q$,'22023','Null cap rejected');
select public.save_shooting_challenge_day('30000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001',current_date-1,50,1,gen_random_uuid(),'Confirmed typing error');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'bonus_total')::int=0,'Correction removes nonexistent bonus effort');
select public.test_assert(not (public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->'players'->0->>'bonus_boss')::boolean,'Badge reflects corrected saved effort');
select public.test_assert((public.get_shooting_challenge('30000000-0000-0000-0000-000000000003')->>'corrected')::boolean,'Correction remains visibly recorded');
reset role;
set role anon;
select public.test_denied($q$select public.set_shooting_challenge_cap('30000000-0000-0000-0000-000000000003',500,400)$q$,'42501','Anonymous cap edits denied');
reset role;
